import{_ as i,o as s,c as t,a2 as a}from"./chunks/framework.uw_ZoRon.js";const d=JSON.parse('{"title":"Phase 2 — Mailboxes & message passing","description":"","frontmatter":{},"headers":[],"relativePath":"phases/phase-02-messaging.md","filePath":"phases/phase-02-messaging.md"}'),h={name:"phases/phase-02-messaging.md"};function o(n,e,r,l,c,p){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="phase-2-—-mailboxes-message-passing" tabindex="-1">Phase 2 — Mailboxes &amp; message passing <a class="header-anchor" href="#phase-2-—-mailboxes-message-passing" aria-label="Permalink to &quot;Phase 2 — Mailboxes &amp; message passing&quot;">​</a></h1><p>Isolation without communication is useless — Phase 2 gives every process a private mailbox and one rule: the only way to share data is to copy a message into someone else&#39;s queue.</p><h2 id="why-this-phase" tabindex="-1">Why this phase <a class="header-anchor" href="#why-this-phase" aria-label="Permalink to &quot;Why this phase&quot;">​</a></h2><p>Phase 1 proved processes can spawn and die cheaply. But isolated processes that can&#39;t talk to each other are just threads with extra steps. The actor model&#39;s core insight — copy a message into the recipient&#39;s mailbox, never share memory — is what makes &quot;let it crash&quot; work, what makes cross-Wasm-instance messaging possible without data races, and what keeps the programming model the same whether processes live on one machine or across a cluster.</p><p>Phase 2 draws that line. After it, every interaction between processes goes through the mailbox. There are no other coordination primitives in the model.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ol><li><strong>One mailbox per process</strong> — a Tokio <code>mpsc::unbounded</code> receiver lives in the process&#39;s <code>Context</code>; the sender half lives in the table entry. No allocation on send; no lock on receive.</li><li><strong><code>Received</code> enum</strong> — a mailbox carries more than user bytes: <code>Message(Vec&lt;u8&gt;)</code>, <code>Down { reference, pid, reason }</code>, and <code>Exit { from, reason }</code>. One channel, one ordering, for messages <em>and</em> signals. The supervision primitives from Phase 3 land here — already designed in.</li><li><strong><code>send(pid, msg) -&gt; bool</code></strong> — enqueues into the target mailbox; returns <code>false</code> for a dead pid. Send never panics, never throws — Erlang semantics.</li><li><strong><code>recv().await</code></strong> — suspends the process until a message arrives, yielding the Tokio worker while parked. The foundation of cheap massive concurrency: a parked process costs nothing.</li><li><strong>Selective receive — <code>recv_match(pred)</code></strong> — scans the mailbox for the first message matching a predicate, stashing non-matches in a <code>saved</code> <code>VecDeque</code> and replaying them on the next receive. Erlang&#39;s selective receive, with full arrival-order preservation for messages left behind.</li></ol><h2 id="design-highlights" tabindex="-1">Design highlights <a class="header-anchor" href="#design-highlights" aria-label="Permalink to &quot;Design highlights&quot;">​</a></h2><ul><li><strong>One channel, not two.</strong> Messages and exit/down signals share a single ordered mailbox, so a process sees one well-defined event stream. No separate signal channel, no per-process two-channel overhead — and signals can&#39;t reorder relative to messages.</li><li><strong><code>Vec&lt;u8&gt;</code> payloads — serialization-agnostic core.</strong> The runtime doesn&#39;t care what&#39;s in a message. Structure is the guest&#39;s concern (and the Wasm ABI&#39;s in Phase 6). JSON, msgpack, raw bytes — all equally supported.</li><li><strong>Send never fails loudly.</strong> Sending to a dead pid returns <code>false</code>. The caller decides what to do; the runtime doesn&#39;t crash. This is one of the properties that makes &quot;let it crash&quot; safe — a crash in one process doesn&#39;t propagate through send calls.</li><li><strong>Selective receive preserves queue order.</strong> Non-matching messages are stashed and replayed first on the next receive. A message skipped today isn&#39;t lost — it arrives in its original position relative to other non-matched messages.</li></ul><h2 id="what-this-unlocks" tabindex="-1">What this unlocks <a class="header-anchor" href="#what-this-unlocks" aria-label="Permalink to &quot;What this unlocks&quot;">​</a></h2><p>Processes are now actors. You can build request/reply patterns, pipelines, broadcast fans, and stateful services — all over message passing, all without shared memory. The ping-pong scenario goes live here and demonstrates ~21M round-trip messages/sec at p50 &lt;1µs, on one machine, in process pairs.</p><p>Phase 3 adds links and monitors — but those are just new variants of <code>Received</code>. The mailbox was already designed to carry them.</p><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes rose-pine-dawn rose-pine-moon catppuccin-latte catppuccin-mocha vitesse-light vitesse-dark one-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D7827E;--shiki-light-font-style:inherit;--shiki-dark:#EA9A97;--shiki-dark-font-style:inherit;--shiki-catpLight:#1E66F5;--shiki-catpLight-font-style:italic;--shiki-catpDark:#89B4FA;--shiki-catpDark-font-style:italic;--shiki-vitLight:#59873A;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#80A665;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#4078F2;--shiki-oneLight-font-style:inherit;--shiki-oneDark:#61AFEF;--shiki-oneDark-font-style:inherit;">cargo</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> run</span><span style="--shiki-light:#286983;--shiki-dark:#3E8FB0;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#A65E2B;--shiki-vitDark:#C99076;--shiki-oneLight:#986801;--shiki-oneDark:#D19A66;"> -p</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> rusm-bench</span><span style="--shiki-light:#286983;--shiki-dark:#3E8FB0;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#A65E2B;--shiki-vitDark:#C99076;--shiki-oneLight:#986801;--shiki-oneDark:#D19A66;"> --</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> run</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> ping-pong</span><span style="--shiki-light:#D7827E;--shiki-dark:#EA9A97;--shiki-catpLight:#FE640B;--shiki-catpDark:#FAB387;--shiki-vitLight:#2F798A;--shiki-vitDark:#4C9A91;--shiki-oneLight:#986801;--shiki-oneDark:#D19A66;"> 5</span><span style="--shiki-light:#797593;--shiki-light-font-style:italic;--shiki-dark:#908CAA;--shiki-dark-font-style:italic;--shiki-catpLight:#9CA0B0;--shiki-catpLight-font-style:italic;--shiki-catpDark:#6C7086;--shiki-catpDark-font-style:italic;--shiki-vitLight:#A0ADA0;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#758575DD;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#A0A1A7;--shiki-oneLight-font-style:italic;--shiki-oneDark:#7F848E;--shiki-oneDark-font-style:italic;">    #</span><span style="--shiki-light:#9893A5;--shiki-light-font-style:italic;--shiki-dark:#6E6A86;--shiki-dark-font-style:italic;--shiki-catpLight:#9CA0B0;--shiki-catpLight-font-style:italic;--shiki-catpDark:#6C7086;--shiki-catpDark-font-style:italic;--shiki-vitLight:#A0ADA0;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#758575DD;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#A0A1A7;--shiki-oneLight-font-style:italic;--shiki-oneDark:#7F848E;--shiki-oneDark-font-style:italic;"> ~21M msgs/sec, round-trip p50 &lt;1µs</span></span></code></pre></div><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Phase complete. ~21M messages/sec, round-trip p50 &lt;1µs. Ping-pong is live in the dashboard.</p><hr><p><em>Next: <a href="./phase-03-supervision">Phase 3</a> — links, monitors, supervision: failures propagate, supervisors restart, fault-recovery goes live at ~285k restarts/sec.</em></p>',18)])])}const g=i(h,[["render",o]]);export{d as __pageData,g as default};
